// Valida el pedido antes de tocar la planilla.
// Esperamos {"remitos": [...]} con entre 1 y 500 números.
const body = $json.body || {};
const remitos = body.remitos;
if (!Array.isArray(remitos) || remitos.length === 0) {
  return [{ json: { valido: false, status: 400, error: 'Falta la lista "remitos" o está vacía.' } }];
}
if (remitos.length > 500) {
  return [{ json: { valido: false, status: 400, error: 'Máximo 500 remitos por pedido.' } }];
}
// Cada remito puede venir solo ("0003-123") o con datos para la búsqueda aproximada
// ({remito, id_transportista, fecha_viaje}).
const lista = remitos.map(r => (typeof r === 'object' && r !== null) ? r : { remito: String(r) });
if (lista.some(r => !r.remito)) {
  return [{ json: { valido: false, status: 400, error: 'Hay elementos sin "remito".' } }];
}
return [{ json: { valido: true, remitos: lista } }];

// Cruza los remitos pedidos contra la hoja Cargas.
// Se compara por número normalizado (solo dígitos, sin ceros adelante), como en la P2.
const norm = s => String(s ?? '').replace(/\D/g, '').replace(/^0+/, '');
const cargas = $input.all().map(i => i.json).filter(c => c.id_carga);
const porRemito = {};
for (const c of cargas) (porRemito[norm(c.remito_ctg)] ??= []).push(c);

const pedidos = $('Validar pedido').first().json.remitos;
const dias = (a, b) => Math.abs(Date.parse(a) - Date.parse(b)) / 864e5;
const resultados = pedidos.map(p => {
  const r = p.remito;
  const lista = porRemito[norm(r)] || [];
  let estado = 'No encontrada';
  if (lista.length > 1) estado = 'Múltiples cargas';
  else if (lista.length === 1) estado = lista[0].estado;   // Disponible | Facturada
  return {
    remito: r,
    remito_norm: norm(r),
    estado,
    cargas: lista.map(c => ({
      id_carga: c.id_carga,
      id_transportista: c.id_transportista,
      fecha_viaje: c.fecha_viaje,
      estado: c.estado,
      id_factura_que_la_uso: c.id_factura_que_la_uso || null,
    })),
    // Búsqueda aproximada: solo si no apareció y nos dijeron transportista y fecha.
    // Cargas disponibles del mismo transportista con hasta 2 días de diferencia.
    similares: (lista.length === 0 && p.id_transportista && p.fecha_viaje)
      ? cargas.filter(c => c.estado === 'Disponible' && c.id_transportista === p.id_transportista
                        && dias(c.fecha_viaje, p.fecha_viaje) <= 2)
              .map(c => ({ id_carga: c.id_carga, remito_ctg: c.remito_ctg, fecha_viaje: c.fecha_viaje }))
      : [],
  };
});
return [{ json: { consultados: pedidos.length, encontrados: resultados.filter(x => x.cargas.length).length, resultados } }];
